// src/lib/plattform/backend/demo/speicher.js
//
// Datei-Datenbank des Demo-Backends: eine JSON-Datei unter .data/plattform.json
// (steht in .gitignore). Schreiben nur unter einer Sperrdatei (funktioniert auch,
// wenn Next.js das Modul mehrfach lädt) und atomar über Datei + Umbenennen.
// Uploads liegen unter .data/uploads/ mit zufälligen Dateinamen.

import { promises as fs, readFileSync, statSync } from "node:fs";
import path from "node:path";

export const DATEN_ORDNER = path.join(process.cwd(), ".data");
export const UPLOAD_ORDNER = path.join(DATEN_ORDNER, "uploads");
const DATEI = path.join(DATEN_ORDNER, "plattform.json");
const SPERRE = path.join(DATEN_ORDNER, "plattform.lock");
const SCHEMA = 2; // 2: Benachrichtigungen, Postausgang, Aufgaben, Checklisten

let cache = null; // { mtimeMs, size, db }

const warte = (ms) => new Promise((r) => setTimeout(r, ms));

async function sperren() {
  await fs.mkdir(DATEN_ORDNER, { recursive: true });
  const start = Date.now();
  for (;;) {
    try {
      const h = await fs.open(SPERRE, "wx");
      await h.writeFile(String(process.pid));
      await h.close();
      return;
    } catch (e) {
      if (e.code !== "EEXIST") throw e;
      // verwaiste Sperre (Prozess abgestürzt) nach 10 s entfernen
      try {
        const st = await fs.stat(SPERRE);
        if (Date.now() - st.mtimeMs > 10000) await fs.rm(SPERRE, { force: true });
      } catch {
        /* inzwischen weg */
      }
      if (Date.now() - start > 8000) throw new Error("Demo-Datenbank ist gesperrt");
      await warte(10 + Math.random() * 20);
    }
  }
}

async function entsperren() {
  await fs.rm(SPERRE, { force: true }).catch(() => {});
}

// BEWUSST SYNCHRON: React 19 schneidet im Dev-Modus den Rückgabewert von
// awaited I/O (fs.promises) für die Debug-Anzeige mit und liefert ihn im
// HTML aus – das war die komplette Demo-Datenbank inkl. Passwort-Hashes auf
// jeder Seite (2–5 MB). Synchrones Lesen erzeugt keinen solchen I/O-Eintrag.
async function dateiLesen() {
  try {
    const st = statSync(DATEI);
    if (cache && cache.mtimeMs === st.mtimeMs && cache.size === st.size) return structuredClone(cache.db);
    const roh = readFileSync(DATEI, "utf8");
    const db = JSON.parse(roh);
    cache = { mtimeMs: st.mtimeMs, size: st.size, db };
    return structuredClone(db);
  } catch (e) {
    if (e.code === "ENOENT") return null;
    throw e;
  }
}

async function dateiSchreiben(db) {
  const tmp = `${DATEI}.${process.pid}.${Date.now()}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(db, null, 1), "utf8");
  for (let i = 0; ; i++) {
    try {
      await fs.rename(tmp, DATEI);
      break;
    } catch (e) {
      // Windows: Ziel kurzzeitig von einem Leser geöffnet
      if (i > 20 || !["EPERM", "EBUSY", "EACCES"].includes(e.code)) {
        await fs.rm(tmp, { force: true }).catch(() => {});
        throw e;
      }
      await warte(15);
    }
  }
  cache = null;
}

let seedFn = null;
/** Seed-Funktion registrieren (liefert eine neue, befüllte Datenbank) */
export function seedSetzen(fn) {
  seedFn = fn;
}

async function sicherstellen() {
  const db = await dateiLesen();
  if (db && db.schema === SCHEMA) return db;
  await sperren();
  try {
    const erneut = await dateiLesen();
    if (erneut && erneut.schema === SCHEMA) return erneut;
    const neu = await seedFn();
    neu.schema = SCHEMA;
    await dateiSchreiben(neu);
    return structuredClone(neu);
  } finally {
    await entsperren();
  }
}

/** Nur lesen (Kopie – Änderungen daran werden NICHT gespeichert) */
export async function lesen() {
  return sicherstellen();
}

/** Lesen, ändern, speichern unter Sperre. `fn(db)` darf db verändern und ein Ergebnis liefern. */
export async function aendern(fn) {
  await sicherstellen();
  await sperren();
  try {
    const db = await dateiLesen();
    const ergebnis = await fn(db);
    await dateiSchreiben(db);
    return ergebnis;
  } finally {
    await entsperren();
  }
}

export async function uploadSchreiben(dateiname, daten) {
  await fs.mkdir(UPLOAD_ORDNER, { recursive: true });
  await fs.writeFile(path.join(UPLOAD_ORDNER, path.basename(dateiname)), daten);
}

export async function uploadLesen(dateiname) {
  return fs.readFile(path.join(UPLOAD_ORDNER, path.basename(dateiname)));
}

export async function uploadLoeschen(dateiname) {
  await fs.rm(path.join(UPLOAD_ORDNER, path.basename(dateiname)), { force: true });
}
// src/lib/plattform/backend/demo/kette.js
//
// Hash-Kette des Aktivitätsprotokolls im Demo-Backend (Verfahren: src/lib/plattform/hashkette.js).
//  - protokoll() in demo.js hängt jeden Eintrag über protokollAnhaengen() an (prevHash + hash).
//  - Einführung: vorhandene Einträge werden einmalig in ihrer Reihenfolge „nachgesiegelt“ (markiert).
//  - Einträge, die fremder Code ohne protokoll() ans Ende gehängt hat, werden beim nächsten Eintrag
//    nachgesiegelt und markiert (`nachgesiegelt: true`) – Einfügungen mitten in der Kette,
//    Änderungen und Löschungen erkennt verifyChain().
//  - Archivierung (> 5000 Einträge): der Hash des letzten entfernten Eintrags bleibt als Anker.

import { KETTE_START, verketten, verifyChain } from "../../hashkette";
import { jetzt } from "./hilfen";

const MAX = 5000;

/** Kette einführen, falls noch nicht geschehen (vorhandene Einträge werden nachgesiegelt) */
export function ketteSicher(db) {
  if (!db.kette) einfuehren(db);
}

function einfuehren(db) {
  db.aktivitaeten = db.aktivitaeten || [];
  let prev = KETTE_START;
  let n = 0;
  for (const x of db.aktivitaeten) {
    verketten(x, prev);
    x.nachgesiegelt = true;
    prev = x.hash;
    n++;
  }
  db.kette = { seit: jetzt(), nachgesiegelt: n, anker: null, verfahren: "SHA-256(prevHash + LF + kanonischer Inhalt)" };
}

export function protokollAnhaengen(db, eintrag) {
  db.aktivitaeten = db.aktivitaeten || [];
  const liste = db.aktivitaeten;
  if (!db.kette) einfuehren(db);
  let i = liste.length - 1;
  while (i >= 0 && !liste[i].hash) i--;
  let prev = i >= 0 ? liste[i].hash : db.kette.anker?.hash || KETTE_START;
  for (let j = i + 1; j < liste.length; j++) {
    verketten(liste[j], prev);
    liste[j].nachgesiegelt = true;
    prev = liste[j].hash;
    db.kette.nachgesiegelt = (db.kette.nachgesiegelt || 0) + 1;
  }
  verketten(eintrag, prev);
  liste.push(eintrag);
  if (liste.length > MAX) {
    const weg = liste.splice(0, liste.length - MAX);
    const letzter = weg[weg.length - 1];
    db.kette.anker = { hash: letzter.hash, anzahl: (db.kette.anker?.anzahl || 0) + weg.length, bis: letzter.am };
  }
  return eintrag;
}

/** Kette prüfen (alle Brüche melden) */
export function kettePruefen(db, { alleFehler = true } = {}) {
  const liste = db.aktivitaeten || [];
  const r = verifyChain(liste, { anker: db.kette?.anker, alleFehler });
  return {
    ...r,
    eingefuehrt: !!db.kette,
    seit: db.kette?.seit || null,
    nachgesiegelt: liste.filter((x) => x.nachgesiegelt).length,
    anker: db.kette?.anker || null,
    verfahren: db.kette?.verfahren || "SHA-256(prevHash + LF + kanonischer Inhalt)",
    erster: liste[0] ? { id: liste[0].id, am: liste[0].am } : null,
    letzter: liste.length ? { id: liste[liste.length - 1].id, am: liste[liste.length - 1].am, hash: liste[liste.length - 1].hash } : null,
    geprueftAm: jetzt(),
  };
}
// src/lib/plattform/hashkette.js
//
// Revisionssicheres Aktivitätsprotokoll: Hash-Kette über alle Einträge.
//
//   hash_n = SHA-256( prevHash_n + "\n" + inhalt_n )      mit prevHash_n = hash_(n-1)
//
// `inhalt` ist eine kanonische JSON-Darstellung der fachlichen Felder in fester Reihenfolge
// (id, am, nutzerId, aktion, objektArt, objektId, text, ip). Wer einen Eintrag nachträglich ändert,
// löscht, einfügt oder umsortiert, bricht die Kette ab dieser Stelle – verifyChain() meldet die
// erste Abweichung. Identisches Verfahren in Frappe: plattform/hashkette.py (Feld prev_hash/entry_hash).
//
// Werden alte Einträge archiviert (Demo: > 5000 Einträge), bleibt ein Anker { hash, anzahl, bis }
// stehen: die Prüfung beginnt dann beim Anker-Hash statt beim Startwert.
//
// Nur serverseitig (node:crypto).

import { createHash } from "node:crypto";

export const KETTE_START = "0".repeat(64);
export const KETTE_FELDER = ["id", "am", "nutzerId", "aktion", "objektArt", "objektId", "text", "ip"];

const wert = (v) => (v === undefined || v === null ? "" : String(v));

/** Kanonischer Inhalt eines Eintrags (unabhängig von zusätzlichen Feldern wie `nutzer`) */
export function eintragInhalt(e) {
  return JSON.stringify(KETTE_FELDER.map((k) => [k, wert(e?.[k])]));
}

export function eintragHash(prevHash, e) {
  return createHash("sha256").update(`${prevHash}\n${eintragInhalt(e)}`, "utf8").digest("hex");
}

/** Eintrag an die Kette anhängen: setzt prevHash und hash (verändert das Objekt) */
export function verketten(e, prevHash = KETTE_START) {
  e.prevHash = prevHash || KETTE_START;
  e.hash = eintragHash(e.prevHash, e);
  return e;
}

/**
 * Kette prüfen. `eintraege` in Einfügereihenfolge (älteste zuerst).
 * Liefert { ok, geprueft, fehler: [{ index, id, grund }], letzterHash, start }.
 * Mit `alleFehler: false` (Standard) endet die Prüfung beim ersten Bruch.
 */
export function verifyChain(eintraege = [], { anker = null, alleFehler = false } = {}) {
  const start = anker?.hash || KETTE_START;
  let prev = start;
  const fehler = [];
  let geprueft = 0;
  for (let i = 0; i < eintraege.length; i++) {
    const e = eintraege[i];
    geprueft++;
    let grund = "";
    if (!e?.hash) grund = "Eintrag ohne Hash (ungesichert eingefügt)";
    else if (e.prevHash !== prev) grund = "Verweis auf den Vorgänger passt nicht (Eintrag gelöscht, eingefügt oder umsortiert)";
    else if (eintragHash(prev, e) !== e.hash) grund = "Inhalt wurde nachträglich verändert";
    if (grund) {
      fehler.push({ index: i, id: e?.id || null, am: e?.am || null, grund });
      if (!alleFehler) break;
    }
    prev = e?.hash || prev;
  }
  return { ok: fehler.length === 0, geprueft, anzahl: eintraege.length, fehler, letzterHash: prev, start };
}

