    W.protokoll(db, n, "rechte", "nutzer", u.id, `Backoffice-Rollen: ${r.map((x) => BACKOFFICE_ROLLEN[x].label).join(", ")}`);
    return { id: u.id, backofficeRollen: r };
  });
}

