  kycEinreichen: "kyc.einreichen",
  kycErneut: "kyc.erneut",
  kycStatus: "kyc.status",
  kycFreigabePruefen: "kyc.freigabe",
  kycWarteschlange: "kyc.warteschlange",
  kycFallDetail: "kyc.fall_detail",
