// src/lib/plattform/server/kycDatei.js – Auslieferung einer (entschlüsselten) KYC-Unterlage: kein Cache, nosniff, Sandbox-CSP

export function kycDateiAntwort(meta, daten, { anzeigen = false } = {}) {
  const ascii = String(meta.name || "unterlage").replace(/[^\x20-\x7e]/g, "_").replace(/["\\]/g, "_");
  return new Response(daten, {
    headers: {
      "Content-Type": meta.mime,
      "Content-Length": String(daten.length),
      "Content-Disposition": `${anzeigen ? "inline" : "attachment"}; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(meta.name || "unterlage")}`,
      "Cache-Control": "private, no-store, max-age=0",
      "X-Content-Type-Options": "nosniff",
      "Referrer-Policy": "no-referrer",
      "Content-Security-Policy": "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; sandbox",
    },
  });
}
