WARTESCHLANGE = ("eingereicht", "in_pruefung", "zweitpruefung")
UEBERGAENGE = [
	(("offen", "nachgefordert", "abgelaufen"), "eingereicht", "nutzer"),
	(("eingereicht",), "in_pruefung", "compliance"),
