		score = min(1.0, score)
		if score >= schwelle:
			treffer.append({"eintragId": str(e.get("id")), "euRef": e.get("euRef") or "", "name": best_name, "score": round(score, 3), "geburtsdatum": gd, "programm": e.get("programm") or "", "pruefling": pruefling.get("rolle") or ""})
